/* Styling for tags list */
.c-tags-list {
display: flex;
flex-wrap: wrap;
list-style: none;
margin: 0;
padding: 0;
}

.c-tags-list > li {
margin: 0 10px 10px 0;
padding: 0 35px;
color: #fff;
border-radius: 31px;
background-color: #4ABEEA;
font-size: 1.4rem;
line-height: 1.8;
}

/* General alignment and layout adjustments */
.centered-content {
text-align: center;
margin: auto;
}

.content-section {
margin-bottom: 20px;
}

img {
max-width: 100%;
height: auto;
display: block;
margin: auto;
}

.content-img-left {
float: left;
margin-right: 20px;
max-width: 40%;
}

.content-img-right {
float: right;
margin-left: 20px;
max-width: 40%;
}

ul {
margin: 20px 0;
}

ul li {
margin-bottom: 10px;
}

table {
width: 100%;
border-collapse: collapse;
margin-bottom: 20px;
}

table th, table td {
text-align: left;
padding: 8px;
border-bottom: 1px solid #ddd;
}

